package net.minecraft.entity.player;import net.minecraft.stats.Achievement;import net.minecraft.item.ItemStack;import java.util.*;public class EntityPlayer {public final Set<String> earned=new LinkedHashSet<>();public final Inventory inventory=new Inventory();public final cn.academy.ability.api.data.AbilityData data=new cn.academy.ability.api.data.AbilityData();public void triggerAchievement(Achievement a){if(a.parentAchievement==null||earned.contains(a.parentAchievement.statId))earned.add(a.statId);}public static class Inventory {public ItemStack[] mainInventory=new ItemStack[0];}}
